// index.js
import React from 'react';
import ReactDOM from 'react-dom';
import 'carbon-components/css/carbon-components.min.css';
import { DataTable } from 'carbon-components-react';

const headers = [
  { key: 'name', header: 'Name' },
  { key: 'age', header: 'Age' }
];

const rows = [
  { id: '1', name: 'Alice', age: 30 },
  { id: '2', name: 'Bob', age: 25 }
];

function App() {
  return (
    <div style={{ padding: '2rem' }}>
      <DataTable rows={rows} headers={headers} render={({ rows, headers, getHeaderProps, getSelectionProps }) => (
        <DataTable.TableContainer title="Selectable Table">
          <DataTable.Table>
            <DataTable.TableHead>
              <DataTable.TableRow>
                {/* Header checkbox */}
                <DataTable.TableSelectAll {...getSelectionProps()} />
                {headers.map(header => (
                  <DataTable.TableHeader key={header.key} {...getHeaderProps({ header })}>
                    {header.header}
                  </DataTable.TableHeader>
                ))}
              </DataTable.TableRow>
            </DataTable.TableHead>
            <DataTable.TableBody>
              {rows.map(row => (
                <DataTable.TableRow key={row.id}>
                  {/* Row checkbox cell */}
                  <DataTable.TableSelectRow {...getSelectionProps({ row })} />
                  {row.cells.map(cell => (
                    <DataTable.TableCell key={cell.id}>{cell.value}</DataTable.TableCell>
                  ))}
                </DataTable.TableRow>
              ))}
            </DataTable.TableBody>
          </DataTable.Table>
        </DataTable.TableContainer>
      )} />
    </div>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));

